// Two factors, and each alone opens nothing: a badge (or PIN) presented at
// the reader wired to the "badge" input, and the badge holder's face
// recognized within WINDOW_S seconds of it. Face recognition has no
// liveness check (a printed photo can pass), so the face confirms the
// badge; it never replaces it.

// People allowed through this door: the class names of the face model
// (one class per enrolled person) -> the badge id each one carries.
// "unknown" is never authorized.
const AUTHORIZED = { "Ana Duarte": "0001", "Bruno Sa": "0002" };
// Cosine similarity a face must reach, on top of the device's own
// match threshold, before it counts.
const MIN_CONFIDENCE = 0.45;
// How long one factor waits for the other.
const WINDOW_S = 10;

const now = Date.now();
if (msg.topic === "badge") {
    context.set("badge", { id: String(msg.payload), until: now + WINDOW_S * 1000 });
} else if (!msg.payload || msg.payload.task !== "face") {
    // Only a face recognition device names people: a detection or
    // classification payload with a matching class name is not a face.
    node.status({ fill: "red", shape: "ring", text: "not a face recognition device" });
    return null;
} else {
    const faces = msg.payload.detections || [];
    const allowed = faces.filter(
        (f) => f.class_name in AUTHORIZED && f.confidence >= MIN_CONFIDENCE
    );
    allowed.sort((a, b) => b.confidence - a.confidence);
    context.set("face", allowed.length
        ? { name: allowed[0].class_name, confidence: allowed[0].confidence,
            until: now + WINDOW_S * 1000 }
        : null);
}

const badge = context.get("badge");
const face = context.get("face");
if (!badge || badge.until < now) {
    node.status({ fill: "grey", shape: "ring",
                  text: face && face.until >= now ? face.name + ": waiting for badge" : "no authorized face" });
    return null;
}
if (!face || face.until < now) {
    node.status({ fill: "grey", shape: "ring", text: "badge " + badge.id + ": waiting for face" });
    return null;
}
if (AUTHORIZED[face.name] !== badge.id) {
    node.status({ fill: "red", shape: "dot", text: face.name + " is not badge " + badge.id });
    return null;
}
// One release per badge + face pair.
context.set("badge", null);
context.set("face", null);
node.status({ fill: "green", shape: "dot", text: face.name + " + badge " + badge.id });
return { payload: true, person: face.name, confidence: face.confidence, badge: badge.id };
